const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    const colSums = new Int32Array(M);

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < M; j++) {
            colSums[j] += nextInt();
        }
    }

    let minSum = colSums[0];
    for (let j = 1; j < M; j++) {
        if (colSums[j] < minSum) {
            minSum = colSums[j];
        }
    }

    console.log(minSum);
}

main();
